| type = [[Salvage item]]
| value = 5 {{gold}}
| campaign = [[Nightfall]]
| commonsalvage = [[Pile of Glittering Dust|Piles of Glittering Dust]]
| raresalvage = [[Bolt of Silk|Bolts of Silk]]
}}
</pre>

